/**
 * Browser verification harness for shipbench.dev. See e2e/README.md.
 *
 * Runs against `astro preview` over a **production build**, never `astro dev`.
 * Pagefind's search index is generated by the Pagefind CLI after `astro build`
 * (see the site's `build` script), so it simply does not exist under the dev
 * server — a dev-server harness could not test search at all.
 *
 * Chromium only. Runs in CI, but path-filtered to changes that can actually
 * affect the site — `apps/site/**` and `pnpm-lock.yaml` — because the site
 * declares and imports no `@shipbench/*` package, so a change to core, board,
 * or the CLI cannot alter its browser behaviour. See .github/workflows/e2e.yml.
 *
 * The value here is the four things jsdom structurally cannot do: real WASM
 * search, a real <dialog> focus trap, real first-paint pixels, and real layout
 * for axe.
 */

import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { defineConfig, devices } from '@playwright/test';

const siteDir = fileURLToPath(new URL('.', import.meta.url));
const PORT = Number(process.env.SITE_E2E_PORT ?? 4321);
const BASE_URL = `http://localhost:${PORT}`;

// Fail loudly and usefully rather than letting `astro preview` die on a missing
// directory. `pnpm test:e2e` builds first; a bare `playwright test` may not have.
if (!existsSync(new URL('dist/client/pagefind/pagefind.js', import.meta.url))) {
  throw new Error(
    'No production build found at apps/site/dist/client (with a Pagefind index).\n' +
      'Run `pnpm --filter @shipbench/site test:e2e`, which builds first.',
  );
}

export default defineConfig({
  testDir: './e2e',
  // Stops the preview daemon. The wrapper's signal handlers cover POSIX and CI;
  // this covers Windows, where Playwright terminates rather than signals.
  globalTeardown: './e2e/support/global-teardown.ts',
  // Traces, videos, and failure screenshots. Gitignored — see e2e/README.md.
  outputDir: './e2e/.artifacts',
  fullyParallel: true,
  // Locally, a stray `.only` while narrowing a failure is the whole point. In
  // CI it silently reduces the suite to one test and reports green.
  forbidOnly: Boolean(process.env.CI),
  // Locally zero, because a retry would hide a genuinely flaky assertion from
  // the person who just wrote it. In CI, one — but note this does not hide
  // flake either: Playwright reports a retried-then-passed test as **flaky**
  // rather than passed, so the signal survives while a slow shared runner does
  // not turn the whole workflow red. Raise this only with evidence; the
  // hydration waits in `support/hydration.ts` exist so it should not be needed.
  retries: process.env.CI ? 1 : 0,
  reporter: process.env.CI ? [['github'], ['list']] : [['list']],

  use: {
    baseURL: BASE_URL,
    trace: 'retain-on-failure',
    // Never assert on these. Screenshot *diffing* is deliberately out of scope
    // (baselines churn on every intentional design change); this is only so a
    // failure leaves something to look at.
    screenshot: 'only-on-failure',
  },

  projects: [
    {
      name: 'chromium',
      use: { ...devices['Desktop Chrome'] },
    },
  ],

  webServer: {
    // Wrangler-backed preview, courtesy of @astrojs/cloudflare. Serves exactly
    // what deploys, including /pagefind/*.
    //
    // Launched through a wrapper rather than `astro preview` directly: Astro's
    // preview command daemonizes and exits within seconds, which Playwright
    // reads as the server having died ("Process from config.webServer exited
    // early") before any test runs. The wrapper holds the foreground and stops
    // the server on teardown. See e2e/support/preview-server.mjs.
    command: `node ./e2e/support/preview-server.mjs ${PORT}`,
    cwd: siteDir,
    url: BASE_URL,
    // False deliberately. The wrapper cleans up after itself, so a server on
    // this port means something went wrong rather than something is reusable —
    // and a stale one serves its startup-time asset manifest, making /pagefind/*
    // 404 and the search specs fail as though the index had regressed. Failing
    // on the port conflict is a far cheaper diagnosis than that.
    reuseExistingServer: false,
    timeout: 120_000,
    stdout: 'pipe',
    stderr: 'pipe',
  },
});
